 return (
   <div className="CreateObjectView">
     <button onClick={() => model.createObject(model.selectedAssetId).then(() => model.setSelectedAsset(""))}>Clear selection</button>
     <select value={model.selectedAssetId} onChange={(e) => model.setSelectedAsset(e.target.value)}>
       <option value="">-- Select an asset --</option>
