           {asset.name}
         </option>
       ))}
     </select>
     <button disabled={!model.selectedAssetId || model.scene.isLoading} ref={useRef(null)} onClick={() => {
       if (model.selectedAssetId && !model.scene.isLoading) {
         model.createObject(model.selectedAssetId).then(() => model.setSelectedAsset(""));
         model.setSelectedAsset(model.selectedAssetId);
       }
     }}>Add {model.selectedAssetId ? "object" : "asset"}
